"""Primary XML review of rotary device and explicit laboratory identity reconciliation."""
import xml.etree.ElementTree as E
import ledger as L
from review_batch_0001 import evidence

def main():
 doi='10.1126/sciadv.1501209';path=L.ROOT/'assets/sources/PMC4788491.xml';r=E.parse(path).getroot()
 ev=evidence(path,'https://pmc.ncbi.nlm.nih.gov/articles/PMC4788491/','Article identifiers/date; Introduction, Results, Discussion, Materials and Methods; Fig1–4 captions; supplementary inventory (not SI contents)')
 q=['Acquire SI and inspect routing diagrams S1/S2/S8/S14/S15/S16, staple/scaffold identity and exact variant combinations.','Separate rotor, two clamp components, optional6HB crank extension and assembly-only connector/closure strands; no flattened molecular authoring.','Resolve source wording of22nm rotation tolerance against original figure/geometry; do not silently normalize.','Primary Methods annealing ramp text and stated total duration require reconciliation before protocol extraction.','Full staple sets/native design availability and source completeness remain unverified.']
 p=next(p for p in L.read('publication_reviews') if p['registry_key']==doi)
 p.update(review_stage='fulltext_reviewed',relevance='design_bearing',design_contributions=['new_design','modified_design'],catalog_eligibility='unresolved',access='partial',evidence=[ev],rationale='Primary paper describes a modular passive rotary apparatus:54-helix94bp rotor body and62-helix115bp clamp bodies explicitly packed on honeycomb lattices. A430nm6HB module extends the crank. Static/strong/weak rotor socket variants and one-/three-socket clamp variants alter docking; these are distinct from experimental Mg conditions. SI inventory identifies design diagrams but their content has not been inspected.',unresolved_questions=q,reviewer='Codex primary XML section review',run_id='DISC0005-rotary',date=L.DATE,date_evidence={'date':'2016-02-19','source':ev,'primary_verified':True,'meaning':'Primary XML publication date'})
 L.upsert('publication_reviews',p,'Record primary design contribution and component/assembly distinction')
 d=dict(design_id='RDE0014',publication_keys=[doi],named_objects=['Rotary apparatus: rotor family, clamp family and optional6HB crank module'],core_variant_composition='Rotor54×94bp and clamp62×115bp helical bodies; two clamp instances form bearing. Separate430nm6HB crank module yields heterotetramer. Static rotor adds12×4nt sticky ends; strong permits12 stacking contacts; weak shortens six socket staples. One or three docking sockets per clamp yield two or six sites per bearing. Bracket closure uses separate auxiliary oligonucleotides. Full component sequence mapping pending.',lattice_decision='Primary Fig1 explicitly specifies honeycomb packing for rotor/clamp; extension and variants require source verification',catalog_eligibility='unresolved',source_completeness='not_verified',source_files=[ev],evidence=[ev],outstanding_checks=q,relationships=[],variant_links=[],legacy_record={},review_run='DISC0005-rotary',date=L.DATE)
 old=next((x for x in L.read('design_evidence') if x['design_id']==d['design_id']),None);assert old is None or old['publication_keys']==[doi];L.upsert('design_evidence',d,'Record provisional multi-component family without asserting complete sources')
 edge=next(e for e in L.read('discovery_edges') if e.get('run_id')=='author-dietz-20261105' and e.get('target_metadata',{}).get('printed_number')=='35')
 edge.update(target_key=doi,reconciliation_state='matched_primary_title_authors_journal_and_identifier',identity_evidence=ev);L.upsert('discovery_edges',edge,'Resolve laboratory title against primary XML title, author group, journal and article identifier')
 refs=r.findall('.//ref-list/ref');assert len(refs)==30;known={p['doi']:p['registry_key'] for p in L.read('publication_reviews') if p['doi']}
 for ref in refs:
  ds=[e.text.lower() for e in ref.findall('.//pub-id') if e.get('pub-id-type')=='doi' and e.text];target=known.get(ds[0],ds[0]) if len(ds)==1 else 'reference:rotary2016:'+ref.get('id')
  L.upsert('discovery_edges',dict(edge_id='backward-rotary-20261105:'+ref.get('id'),source_key=doi,target_key=target,relation='cites',evidence_url=ev['url'],local_file=ev['local_file'],sha256=ev['sha256'],locator='XML ref#'+ref.get('id'),target_metadata={'text':' '.join(''.join(ref.itertext()).split()),'explicit_dois':ds},reconciliation_state='matched_explicit_doi; relevance_pending' if target in known.values() else 'pending_identity_and_scope',run_id='backward-rotary-20261105',date=L.DATE),'Retain all rotary paper references without keyword filtering')
 L.upsert('discovery_runs',dict(run_id='backward-rotary-20261105',route='backward_citations',query_or_seed=doi,source_url=ev['url'],date=L.DATE,pagination={'all30_reference_elements_enumerated':True},provider_total=30,retrieved_count=30,deduplicated_additions=30,additions_unit='Citation edges, not eligible works',evidence=[ev],failures=[],closure_state='exhausted',checkpoint='Single primary bibliography enumerated; identity/relevance/recursive discovery remains pending.'),'Save bounded bibliography coverage')
 print(L.validate())
if __name__=='__main__':main()
